<h2>Document index</h2><table><thead><tr><th>#</th><th>Invoice</th><th>Type</th><th>Period</th><th>Payments</th><th>Total</th></tr></thead><tbody>@foreach($booking->invoices->sortBy('period_from') as $invoice)<tr><td>{{ $loop->iteration }}</td><td>{{ $invoice->invoice_number }}</td><td>{{ $invoice->type_label }}</td><td>{{ $invoice->period_from?->format('d M Y') }} - {{ $invoice->period_to?->format('d M Y') }}</td><td>{{ $invoice->payments->count() }}</td><td class="right">AED {{ number_format((float)$invoice->total_amount,2) }}</td></tr>@endforeach</tbody></table>
@php($transferGroups=$booking->invoices->flatMap(fn($item)=>$item->payments)->groupBy(fn($payment)=>$payment->payment_batch_id ?: $payment->id))
