@foreach($booking->invoices->sortBy('period_from') as $invoice)
<section class="page"><div class="invoice-head"><strong>TAX INVOICE - {{ $invoice->invoice_number }} - PAID</strong><br>{{ $invoice->type_label }} | {{ $invoice->period_from?->format('d M Y') }} - {{ $invoice->period_to?->format('d M Y') }}</div>
