<h2>Payment receipts</h2><table><thead><tr><th>Date</th><th>Method / Account</th><th>Bank reference</th><th>Allocation</th><th class="right">Amount</th></tr></thead><tbody>@foreach($invoice->payments->sortBy('payment_date') as $payment)<tr><td>{{ $payment->payment_date?->format('d M Y') }}</td><td>{{ $payment->payment_method }}<br>{{ $payment->bankAccount?->name ?? '-' }}</td><td>{{ $payment->reference ?: '-' }}@if($payment->payment_batch_id)<br><small>Combined transfer</small>@endif</td><td>@foreach(collect($payment->allocation ?? [])->only(['rent','vat','cleaning','agency','tourism','other','deposit']) as $key=>$amount)@if((float)$amount>0){{ ucfirst($key) }}: {{ number_format((float)$amount,2) }}<br>@endif @endforeach</td><td class="right">AED {{ number_format((float)$payment->amount,2) }}</td></tr>@endforeach<tr class="total"><td colspan="4">Paid against this invoice</td><td class="right">AED {{ number_format($invoice->paid_amount,2) }}</td></tr></tbody></table>
